package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.IfMatchVersion;
@RestController @RequestMapping("/api/v2/planning/projects/{projectId}/sections") public class PlanningProjectSectionController {private final PlanningProjectSectionService s;public PlanningProjectSectionController(PlanningProjectSectionService s){this.s=s;}@PostMapping public Mono<PlanningProjectSectionView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID projectId,@Valid@RequestBody CreatePlanningProjectSectionRequest r){return s.create(o,projectId,r);}@GetMapping public Flux<PlanningProjectSectionView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID projectId){return s.list(o,projectId);}@PatchMapping("/{sectionId}")public Mono<ResponseEntity<PlanningProjectSectionView>> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sectionId,@RequestHeader(value="If-Match",required=false)String ifMatch,@Valid@RequestBody UpdatePlanningProjectSectionRequest r){long version=IfMatchVersion.parse(ifMatch);return s.update(o,sectionId,new UpdatePlanningProjectSectionRequest(r.name(),r.position(),version)).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}@DeleteMapping("/{sectionId}")public Mono<ResponseEntity<Void>> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sectionId,@RequestHeader(value="If-Match",required=false)String ifMatch){return s.delete(o,sectionId,IfMatchVersion.parse(ifMatch)).thenReturn(ResponseEntity.noContent().build());}}
